'use strict';
(()=>{
 const section=document.getElementById('presenterStage'),video=document.getElementById('presenterVideo'),speaker=new Audio(),clock=new PresenterSchedule();
 let settings={},isScreen=false,busy=false,enabled=false,voiceEnabled=false,current='',generation=0,clipsPromise,lastTick=Date.now(),retryAt=0,quietUntil=0,activated=false,watchdog,lastSpeechPosition=0,lastSpeechProgress=Date.now(),motionStarted=0,motionHeld=false,winnerSeen='',winnerPending=false,resultShowing=false,supportReady=false,supportQueue=[],commentQueue=[],lastCommentAt=0;
 const likeTotals=new Map(),giftTotals=new Map(),giftThanked=new Map();
 function supportUpdates(r){for(const p of r.likers||[]){const previous=likeTotals.get(p.id)??0;if(supportReady&&previous<=1000&&p.likes>1000&&supportQueue.length<20)supportQueue.push('likeThanks');likeTotals.set(p.id,p.likes||0)}for(const p of r.gifters||[]){const previous=giftTotals.get(p.id)??0;if(supportReady&&p.gifts>previous&&Date.now()-(giftThanked.get(p.id)||0)>=30000&&supportQueue.length<20){supportQueue.push('giftThanks');giftThanked.set(p.id,Date.now())}giftTotals.set(p.id,p.gifts||0)}supportReady=true}
 video.muted=true;video.loop=true;video.playsInline=true;speaker.preload='auto';
 function clips(){return clipsPromise??=Promise.all(['/audio/host-lines.json?v=2','/audio/host-responses.json?v=1'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('host-audio');return r.json()}))).then(([base,extra])=>({clips:{...base.clips,...extra.clips}})).catch(e=>{clipsPromise=null;throw e})}
 function stop(){clearTimeout(watchdog);generation++;speaker.pause();speaker.currentTime=0;busy=false;current=''}
 function active(){return isScreen&&enabled&&voiceEnabled&&settings.sound&&settings.running&&!settings.paused}
 function report(status,detail){window.dispatchEvent(new CustomEvent('race-audio-state',{detail:{status,detail,voice:'bright'}}))}
 async function play(key){busy=true;current=key;const token=++generation;try{const pack=await clips();if(token!==generation||!active()){if(token===generation)stop();return}speaker.src=pack.clips[key];lastSpeechPosition=0;lastSpeechProgress=Date.now();speaker.volume=Math.max(0,Math.min(1,(settings.volume??20)/100));await speaker.play();if(token!==generation)return;section.classList.add('host-speaking');activated=true;clearTimeout(watchdog);watchdog=setTimeout(()=>{stop();retryAt=Date.now()+10000},30000);report('playing','English host')}catch(e){if(token!==generation)return;busy=false;current='';retryAt=Date.now()+10000;report(e.name==='NotAllowedError'?'blocked':'error',e.name==='NotAllowedError'?'click-enable-sound':'host-audio-playback')}}
 speaker.onended=()=>{clearTimeout(watchdog);quietUntil=Date.now()+3000;if(current)clock.complete(current);busy=false;current='';section.classList.remove('host-speaking');report('ready','English host')};speaker.onerror=()=>{stop();retryAt=Date.now()+10000;section.classList.remove('host-speaking')};
 function updatePresenterMotion(){if(!enabled||!isScreen||!settings.running||settings.paused){motionHeld=false;video.pause();return}if(!motionStarted)motionStarted=Date.now();const move=(settings.presenterMoveSeconds??10)*1000,still=(settings.presenterStillSeconds??4)*1000;motionHeld=settings.presenterMotionPauses!==false&&!busy&&(Date.now()-motionStarted)%(move+still)>=move;if(motionHeld)video.pause();else if(video.paused)video.play().catch(()=>{})}
 function update(r,screen){supportUpdates(r);const resultKey=r.round+':'+r.winner;if(resultKey!==winnerSeen){winnerSeen=resultKey;winnerPending=r.winner!==null&&r.winnerResult?.noWinner===false&&!r.winnerResult?.isDemo;if(winnerPending){stop();quietUntil=Date.now()+500}}resultShowing=r.winner!==null;settings=r.settings;isScreen=screen;enabled=settings.presenterEnabled!==false;voiceEnabled=settings.presenterVoice!==false;section.hidden=!enabled;section.style.setProperty('--presenter-height','calc((100svh - var(--live-safe-bottom,28svh)) * '+((settings.presenterHeightPercent??33)/100)+')');clock.configure({countryDelaySeconds:settings.hostCountryDelaySeconds??60,heartsDelaySeconds:settings.hostHeartsDelaySeconds??120,cheerIntervalSeconds:settings.hostCheerIntervalSeconds??120});if(enabled&&isScreen){if(!video.src)video.src='https://huggingface.co/datasets/afgtakrun/nations-race-gamer-character/resolve/main/english-host-back-v2-silent.mp4';updatePresenterMotion()}else video.pause();if(!active()){stop();section.classList.remove('host-speaking')}}
 document.addEventListener('pointerdown',()=>{retryAt=0;activated=true});video.addEventListener('loadedmetadata',()=>window.dispatchEvent(new Event('resize')));
 setInterval(()=>{const now=Date.now(),delta=Math.min(1000,now-lastTick);lastTick=now;updatePresenterMotion();if(!active())return;clock.advance(delta);if(busy){if(speaker.currentTime>lastSpeechPosition+.05){lastSpeechPosition=speaker.currentTime;lastSpeechProgress=now}else if(now-lastSpeechProgress>5000){stop();section.classList.remove('host-speaking');retryAt=now+1000}if(busy&&speaker.paused&&!speaker.ended&&speaker.readyState>=2)speaker.play().catch(()=>{})}if(busy||window.RaceVoice?.busy||now<retryAt||now<quietUntil)return;if(winnerPending){winnerPending=false;play('winner');return}if(resultShowing)return;if(supportQueue.length){play(supportQueue.shift());return}commentQueue=commentQueue.filter(e=>now-e.at<45000);if(commentQueue.length&&now-lastCommentAt>=12000){lastCommentAt=now;play(commentQueue.shift().key);return}const key=clock.next(settings.playMode);if(key)play(key)},250);
 window.RaceHost={update,comment(event){if(!isScreen||settings.commentReactions===false||!['countryReply','helloReply','carReply','helpReply','cheerReply','thanksReply'].includes(event.key))return;let box=section.querySelector('.host-comment-reply');if(!box){box=document.createElement('div');box.className='host-comment-reply';section.append(box)}box.replaceChildren();const name=document.createElement('strong');name.textContent=event.name||'Viewer';box.append(name,document.createTextNode(' · '+event.message));if(event.country?.flag){const code=Array.from(event.country.flag).map(c=>String.fromCharCode(c.codePointAt(0)-0x1f1e6+97)).join('');if(/^[a-z]{2}$/.test(code)){const flag=document.createElement('img');flag.src='/flags/'+code+'.svg';flag.alt=event.country.name;box.prepend(flag)}}box.hidden=false;clearTimeout(box._hide);box._hide=setTimeout(()=>box.hidden=true,6500);if(active()&&commentQueue.length<5)commentQueue.push({key:event.key,at:Date.now()})},recover(){updatePresenterMotion();if(busy&&speaker.paused&&!speaker.ended&&active())speaker.play().catch(()=>{})},arrival(){if(active())clock.arrival()},quiet(ms=15000){stop();quietUntil=Date.now()+ms;section.classList.remove('host-speaking')},get busy(){return busy},get enabled(){return enabled&&voiceEnabled},get clock(){return clock},get audio(){return speaker},get activated(){return activated},get motionHeld(){return motionHeld}};
})();
